import {randomBytes} from 'node:crypto';
import * as wire from './codec.mjs';
import {createHasher, buildTree, extractPath, pathRoot} from './tree.mjs';
import {nativeProvider} from './native.mjs';
import {portableProvider} from './portable.mjs';
export * from './codec.mjs';
export {KEY_MATERIAL_FORMAT} from './native.mjs';
const {requireThat, VERSION, LIMIT, encodeFields, encodeContext, encodeDescriptor, encodeCertificate,
  decodeCertificate, encodeWhole, decodeWhole, encodeMember, decodeMember, encodeProof, decodeProof, validateMessages, bytes} = wire;
const privateKeys = new WeakMap(), batches = new WeakMap();
const token = () => Object.freeze(Object.create(null));
