    clear() { cache.clear(); publicKeys.clear(); handles = new WeakMap(); },
    stats() { return Object.freeze({cachedCertificates: cache.size, cachedPublicKeyPairs: publicKeys.size,
      signatureChecks, cacheHits, publicKeyImports}); },
